def solution() -> int:
    weights = [9, 5]
    total = sum(weights)
    target = total // 2
    # DP set for achievable sums up to target
    achievable = {0}
    for w in weights:
        new_sums = set()
        for s in achievable:
            if s + w <= target:
                new_sums.add(s + w)
        achievable.update(new_sums)
    best = max(achievable)
    diff = total - 2 * best
    return int(diff)

