import heapq
from typing import List, Tuple

def solution() -> Tuple[List[int], int]:
    # Graph definition (directed)
    graph = {
        0: [(3, 4)],
        1: [(0, 1), (3, 5), (2, 1)],
        2: [(3, 1)],
        3: []
    }
    start, target = 0, 3
    # Dijkstra's algorithm
    dist = {node: float('inf') for node in graph}
    prev = {}
    dist[start] = 0
    heap = [(0, start)]
    while heap:
        d, u = heapq.heappop(heap)
        if d != dist[u]:
            continue
        if u == target:
            break
        for v, w in graph[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                prev[v] = u
                heapq.heappush(heap, (nd, v))
    # Reconstruct shortest path
    path = []
    node = target
    while True:
        path.append(node)
        if node == start:
            break
        node = prev.get(node)
        if node is None:
            break
    path.reverse()
    return path, int(dist[target])

