from typing import List, Tuple
import heapq

def solution() -> Tuple[List[int], int]:
    # Define the directed graph as adjacency list
    graph = {
        0: [(1, 2)],
        1: [(3, 7), (4, 7)],
        2: [(0, 1), (1, 3)],
        3: [(0, 2)],
        4: []
    }

    start, target = 0, 4
    # Dijkstra's algorithm
    dist = {node: float('inf') for node in graph}
    prev = {node: None for node in graph}
    dist[start] = 0
    heap = [(0, start)]

    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        if u == target:
            break
        for v, w in graph[u]:
            alt = d + w
            if alt < dist[v]:
                dist[v] = alt
                prev[v] = u
                heapq.heappush(heap, (alt, v))

    # Reconstruct path
    path: List[int] = []
    node = target
    if dist[target] == float('inf'):
        return ([], -1)  # no path
    while node is not None:
        path.append(node)
        node = prev[node]
    path.reverse()
    return (path, dist[target])

