    from collections import deque
    for start in range(1, 7):
        if start not in colors:
            colors[start] = 'A'
            queue = deque([start])
            while queue:
                v = queue.popleft()
                cur = colors[v]
                nxt = 'B' if cur == 'A' else 'A'
