        (5, 7)
    ]
    vertices = {i for e in edges for i in e}
    adj: Dict[int, List[int]] = {v: [] for v in vertices}
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    colors = ['A', 'B', 'C']
    assignment: Dict[int, str] = {}

    def backtrack(v_idx: int) -> bool:
        if v_idx == len(vertices):
            return True
        v = list(sorted(vertices))[v_idx]
        for col in colors:
            # check feasibility
            if all(assignment.get(nb) != col for nb in adj[v]):
                assignment[v] = col
                if backtrack(v_idx + 1):
                    return True
                del assignment[v]
        return False

    success = backtrack(0)
    if not success:
        raise ValueError("No 3‑coloring exists for the given graph")
    return assignment

