code_question:
from collections import deque

def solution():
    # adjacency list of the given graph
    graph = {
        1: [3, 4, 8],
        2: [4, 7],
        3: [1],
        4: [1, 2],
        5: [8],
        6: [8],
        7: [2],
        8: [1, 5, 6]
    }

    # dictionary that will hold the color of each vertex
    color = {}

    # perform a BFS for each component of the graph
    for start in graph:
        if start not in color:
            color[start] = 'A'
            dq = deque([start])
            while dq:
                v = dq.popleft()
                for nb in graph[v]:
                    if nb in color:
                        if color[nb] == color[v]:
                            raise ValueError('Graph is not bipartite')
                    else:
                        color[nb] = 'B' if color[v] == 'A' else 'A'
                        dq.append(nb)
    return color

if __name__ == '__main__':
    print(solution())

